lines=packet.read_text().splitlines()
log=base/'read-log.jsonl'
now=datetime.datetime.now(datetime.timezone.utc).isoformat()
log.write_text(''.join(json.dumps({'path':str(base/p),'timestamp':now},ensure_ascii=False)+'\n' for p in ['extraction-prompt.txt','packet.md']))
def ev(patterns):
 out=[]
 for i,line in enumerate(lines,1):
  matches=[p for p in patterns if p in line]
  if matches: out.append({'line_start':i,'line_end':i,'quote':min(matches,key=len)})
 return out
facts=[]
def f(meaning,*patterns,modality='asserted'):
 evidence=ev(patterns)
 if not evidence: raise ValueError(meaning)
 facts.append({'id':f'F{len(facts)+1}','meaning':meaning,'modality':modality,'evidence':evidence})
